-- ============ ENUM TYPES ============
do $$ begin create type public.app_role as enum ('admin', 'moderator', 'user'); exception when duplicate_object then null; end $$;

-- ============ TABLES ============
create table if not exists public.activity_log (
  id uuid not null default gen_random_uuid(),
  user_id uuid not null,
  action text not null,
  reference_id uuid,
  metadata jsonb,
  created_at timestamp with time zone not null default now()
);
create table if not exists public.availability_slots (
  id uuid not null default gen_random_uuid(),
  space_id uuid not null,
  start_time timestamp with time zone not null,
  end_time timestamp with time zone not null,
  is_booked boolean not null default false
);
create table if not exists public.bookings (
  id uuid not null default gen_random_uuid(),
  space_id uuid not null,
  renter_id uuid not null,
  host_id uuid not null,
  start_time timestamp with time zone not null,
  end_time timestamp with time zone not null,
  total_price numeric(10,2) not null,
  status text not null default 'pending'::text,
  payment_status text not null default 'unpaid'::text,
  stripe_session_id text,
  qr_checkin_code text,
  checked_in_at timestamp with time zone,
  checked_out_at timestamp with time zone,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  platform_fee numeric not null default 0,
  reservation_fee numeric not null default 0,
  host_earning numeric not null default 0,
  amount_charged numeric not null default 0,
  paddle_transaction_id text,
  cancelled_at timestamp with time zone,
  cancelled_by uuid,
  cancellation_reason text,
  refund_amount numeric not null default 0,
  paddle_refund_id text,
  earnings_clear_at timestamp with time zone,
  earnings_released_at timestamp with time zone,
  hold_expires_at timestamp with time zone
);
create table if not exists public.dispute_events (
  id uuid not null default gen_random_uuid(),
  dispute_id uuid not null,
  actor_id uuid,
  from_status text,
  to_status text not null,
  note text,
  created_at timestamp with time zone not null default now()
);
create table if not exists public.disputes (
