CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$
;

CREATE OR REPLACE FUNCTION public.settle_booking_payment(p_booking_id uuid, p_transaction_id text, p_amount_charged numeric, p_env text DEFAULT 'live'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE b public.bookings; v_fee numeric; v_res numeric := 1; v_earn numeric; v_rate numeric;
        v_pending numeric; v_space text; v_expected numeric;
BEGIN
  SELECT * INTO b FROM public.bookings WHERE id = p_booking_id FOR UPDATE;
  IF b.id IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF b.payment_status IN ('paid','refund_pending','refunded') THEN RETURN 'already_settled'; END IF;

  -- Somebody else confirmed this slot while the driver was paying.
  IF EXISTS (
    SELECT 1 FROM public.bookings o
    WHERE o.space_id = b.space_id AND o.id <> b.id
      AND o.status IN ('confirmed','active')
      AND tstzrange(o.start_time, o.end_time, '[)') && tstzrange(b.start_time, b.end_time, '[)')
  ) THEN
    UPDATE public.bookings SET
      status = 'cancelled', payment_status = 'refund_pending',
      cancelled_at = now(), cancellation_reason = 'Slot was taken before payment completed',
      amount_charged = COALESCE(p_amount_charged, 0),
      refund_amount = COALESCE(p_amount_charged, 0),
      paddle_transaction_id = p_transaction_id, updated_at = now()
    WHERE id = b.id;

    INSERT INTO public.notifications(user_id, kind, title, body, link, booking_id)
    VALUES (b.renter_id, 'payment', 'Reservation unavailable — refund on the way',
      'Another driver confirmed this slot first, so your payment is being refunded in full.',
      '/bookings', b.id);
    RETURN 'conflict';
  END IF;

  v_rate := public.host_commission_rate(b.host_id, p_env);
  v_fee := round(b.total_price * v_rate, 2);
  v_earn := round(b.total_price - v_fee, 2);
  v_expected := round(b.total_price + v_fee + v_res, 2);

  IF p_amount_charged IS NOT NULL AND p_amount_charged < v_expected - 0.05 THEN
    RAISE EXCEPTION 'Underpayment for booking %: charged %, expected %', b.id, p_amount_charged, v_expected;
  END IF;

  UPDATE public.bookings SET
    payment_status = 'paid', status = 'confirmed',
    platform_fee = v_fee, reservation_fee = v_res, host_earning = v_earn,
    amount_charged = COALESCE(p_amount_charged, v_expected),
    paddle_transaction_id = p_transaction_id,
    qr_checkin_code = COALESCE(b.qr_checkin_code, encode(gen_random_bytes(9), 'hex')),
    earnings_clear_at = b.end_time + interval '24 hours',
    hold_expires_at = NULL,
    updated_at = now()
  WHERE id = b.id;

  INSERT INTO public.host_wallets(host_id) VALUES (b.host_id) ON CONFLICT (host_id) DO NOTHING;
  UPDATE public.host_wallets SET
    pending_clearance = pending_clearance + v_earn, updated_at = now()
  WHERE host_id = b.host_id RETURNING pending_clearance INTO v_pending;

  INSERT INTO public.wallet_transactions(host_id, booking_id, kind, amount, balance_after, note)
  VALUES (b.host_id, b.id, 'earning_pending', v_earn, v_pending,
    'Booking paid — held in clearance until 24h after the stay (net of ' || round(v_rate*100) || '% commission)');

  SELECT title INTO v_space FROM public.parking_spaces WHERE id = b.space_id;

  INSERT INTO public.notifications(user_id, kind, title, body, link, booking_id) VALUES
    (b.renter_id, 'booking_confirmed', 'Booking confirmed',
      'Your payment went through. Your check-in code is ready for ' || COALESCE(v_space,'your space') || '.', '/bookings', b.id),
    (b.host_id, 'payment', 'You earned ' || to_char(v_earn, 'FM999999990.00'),
      'A booking for ' || COALESCE(v_space,'your space') || ' was paid. Funds clear 24h after the stay ends.', '/host/earnings', b.id);

  RETURN 'settled';
END; $function$
;

CREATE OR REPLACE FUNCTION public.submit_review(p_booking_id uuid, p_rating integer, p_comment text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_b record;
  v_review_id uuid;
  v_avg numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF p_rating < 1 OR p_rating > 5 THEN RAISE EXCEPTION 'Rating must be 1..5'; END IF;

  SELECT * INTO v_b FROM public.bookings WHERE id = p_booking_id;
  IF v_b.id IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF v_uid <> v_b.renter_id THEN RAISE EXCEPTION 'Only renter can review'; END IF;
  IF v_b.status <> 'completed' THEN RAISE EXCEPTION 'Booking not completed yet'; END IF;

  IF EXISTS (SELECT 1 FROM public.reviews WHERE booking_id = p_booking_id AND reviewer_id = v_uid) THEN
    RAISE EXCEPTION 'Already reviewed';
  END IF;

  INSERT INTO public.reviews (booking_id, reviewer_id, reviewee_id, space_id, rating, comment)
  VALUES (p_booking_id, v_uid, v_b.host_id, v_b.space_id, p_rating, NULLIF(p_comment,''))
  RETURNING id INTO v_review_id;

  SELECT AVG(rating)::numeric(3,2) INTO v_avg
    FROM public.reviews WHERE reviewee_id = v_b.host_id;

  UPDATE public.profiles
     SET rating = COALESCE(v_avg, 0),
         trust_score = LEAST(100, 50 + LEAST(50, total_bookings * 2) + (COALESCE(v_avg,0)::int * 2))
   WHERE id = v_b.host_id;

  RETURN v_review_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.users_share_booking(_a uuid, _b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE (b.renter_id = _a AND b.host_id = _b)
       OR (b.renter_id = _b AND b.host_id = _a)
  );
$function$
;


-- ============ TRIGGERS ============
CREATE TRIGGER booking_activity AFTER INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION log_booking_activity();
CREATE TRIGGER trg_bookings_updated_at BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_notify_booking_insert AFTER INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_on_booking();
CREATE TRIGGER trg_notify_booking_update AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION notify_on_booking();
CREATE TRIGGER trg_disputes_updated_at BEFORE UPDATE ON public.disputes FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_log_dispute_event AFTER INSERT OR UPDATE ON public.disputes FOR EACH ROW EXECUTE FUNCTION log_dispute_event();
CREATE TRIGGER host_wallets_updated_at BEFORE UPDATE ON public.host_wallets FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_notify_on_message AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION notify_on_message();
CREATE TRIGGER trg_spaces_updated_at BEFORE UPDATE ON public.parking_spaces FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER payout_requests_updated_at BEFORE UPDATE ON public.payout_requests FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER review_activity AFTER INSERT ON public.reviews FOR EACH ROW EXECUTE FUNCTION log_review_activity();
CREATE TRIGGER support_tickets_updated_at BEFORE UPDATE ON public.support_tickets FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ============ ROW LEVEL SECURITY ============
alter table public.activity_log enable row level security;
alter table public.availability_slots enable row level security;
alter table public.bookings enable row level security;
alter table public.dispute_events enable row level security;
alter table public.disputes enable row level security;
alter table public.host_wallets enable row level security;
alter table public.messages enable row level security;
alter table public.notifications enable row level security;
alter table public.parking_spaces enable row level security;
alter table public.payout_requests enable row level security;
alter table public.profile_contacts enable row level security;
alter table public.profiles enable row level security;
alter table public.reviews enable row level security;
alter table public.subscriptions enable row level security;
alter table public.support_tickets enable row level security;
alter table public.user_roles enable row level security;
alter table public.wallet_transactions enable row level security;

create policy "Admins view all activity" on public.activity_log as PERMISSIVE for SELECT to authenticated using (has_role(auth.uid(), 'admin'::app_role));
create policy "Users insert own activity" on public.activity_log as PERMISSIVE for INSERT to authenticated with check ((auth.uid() = user_id));
create policy "Users view own activity" on public.activity_log as PERMISSIVE for SELECT to authenticated using ((auth.uid() = user_id));
create policy "Hosts manage own slots" on public.availability_slots as PERMISSIVE for ALL to public using ((space_id IN ( SELECT parking_spaces.id
   FROM parking_spaces
  WHERE (parking_spaces.host_id = auth.uid()))));
create policy "Hosts view own slots" on public.availability_slots as PERMISSIVE for SELECT to authenticated using ((space_id IN ( SELECT parking_spaces.id
   FROM parking_spaces
  WHERE (parking_spaces.host_id = auth.uid()))));
create policy "Signed-in users view slots of active spaces" on public.availability_slots as PERMISSIVE for SELECT to authenticated using ((space_id IN ( SELECT parking_spaces.id
   FROM parking_spaces
  WHERE (parking_spaces.is_active = true))));
create policy "Admins view all bookings" on public.bookings as PERMISSIVE for SELECT to authenticated using (has_role(auth.uid(), 'admin'::app_role));
create policy "Users view own bookings" on public.bookings as PERMISSIVE for SELECT to authenticated using (((auth.uid() = renter_id) OR (auth.uid() = host_id)));
create policy "Admins view all dispute events" on public.dispute_events as PERMISSIVE for SELECT to authenticated using (has_role(auth.uid(), 'admin'::app_role));
create policy "Involved parties view dispute events" on public.dispute_events as PERMISSIVE for SELECT to authenticated using ((dispute_id IN ( SELECT d.id
   FROM (disputes d
     JOIN bookings b ON ((b.id = d.booking_id)))
  WHERE ((b.renter_id = auth.uid()) OR (b.host_id = auth.uid())))));
create policy "Admins update disputes" on public.disputes as PERMISSIVE for UPDATE to authenticated using (has_role(auth.uid(), 'admin'::app_role)) with check (has_role(auth.uid(), 'admin'::app_role));
create policy "Admins view all disputes" on public.disputes as PERMISSIVE for SELECT to authenticated using (has_role(auth.uid(), 'admin'::app_role));
create policy "Involved parties view disputes" on public.disputes as PERMISSIVE for SELECT to authenticated using ((booking_id IN ( SELECT bookings.id
   FROM bookings
  WHERE ((bookings.renter_id = auth.uid()) OR (bookings.host_id = auth.uid())))));
create policy "Users raise disputes on own bookings" on public.disputes as PERMISSIVE for INSERT to authenticated with check (((auth.uid() = raised_by) AND (booking_id IN ( SELECT bookings.id
   FROM bookings
  WHERE ((bookings.renter_id = auth.uid()) OR (bookings.host_id = auth.uid()))))));
create policy "Hosts view own wallet" on public.host_wallets as PERMISSIVE for SELECT to authenticated using (((auth.uid() = host_id) OR has_role(auth.uid(), 'admin'::app_role)));
create policy "messages insert parties" on public.messages as PERMISSIVE for INSERT to authenticated with check (((sender_id = auth.uid()) AND is_booking_party(booking_id, auth.uid())));
create policy "messages mark read" on public.messages as PERMISSIVE for UPDATE to authenticated using (is_booking_party(booking_id, auth.uid())) with check (is_booking_party(booking_id, auth.uid()));
create policy "messages read parties" on public.messages as PERMISSIVE for SELECT to authenticated using (is_booking_party(booking_id, auth.uid()));
create policy "own notifications delete" on public.notifications as PERMISSIVE for DELETE to authenticated using ((auth.uid() = user_id));
create policy "own notifications read" on public.notifications as PERMISSIVE for SELECT to authenticated using ((auth.uid() = user_id));
create policy "own notifications update" on public.notifications as PERMISSIVE for UPDATE to authenticated using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "Active spaces are viewable by everyone" on public.parking_spaces as PERMISSIVE for SELECT to anon, authenticated using (((is_active = true) OR (host_id = auth.uid())));
create policy "Hosts delete own spaces" on public.parking_spaces as PERMISSIVE for DELETE to authenticated using ((auth.uid() = host_id));
create policy "Hosts insert own spaces" on public.parking_spaces as PERMISSIVE for INSERT to authenticated with check ((auth.uid() = host_id));
create policy "Hosts update own spaces" on public.parking_spaces as PERMISSIVE for UPDATE to authenticated using ((auth.uid() = host_id)) with check ((auth.uid() = host_id));
create policy "Hosts view own payouts" on public.payout_requests as PERMISSIVE for SELECT to authenticated using (((auth.uid() = host_id) OR has_role(auth.uid(), 'admin'::app_role)));
create policy "Booking counterparties view phone" on public.profile_contacts as PERMISSIVE for SELECT to authenticated using (users_share_booking(auth.uid(), user_id));
create policy "Owner manages own phone" on public.profile_contacts as PERMISSIVE for ALL to authenticated using ((auth.uid() = user_id)) with check ((auth.uid() = user_id));
create policy "Profiles visible to self, counterparties and admins" on public.profiles as PERMISSIVE for SELECT to authenticated using (((id = auth.uid()) OR users_share_booking(auth.uid(), id) OR has_role(auth.uid(), 'admin'::app_role)));
create policy "Users can insert their own profile" on public.profiles as PERMISSIVE for INSERT to public with check ((auth.uid() = id));
create policy "Users can update their own profile" on public.profiles as PERMISSIVE for UPDATE to public using ((auth.uid() = id));
create policy "Anyone can view reviews" on public.reviews as PERMISSIVE for SELECT to public using (true);
create policy "Reviews viewable by everyone" on public.reviews as PERMISSIVE for SELECT to public using (true);
create policy "Users view own subscription" on public.subscriptions as PERMISSIVE for SELECT to authenticated using ((auth.uid() = user_id));
create policy "Admins update tickets" on public.support_tickets as PERMISSIVE for UPDATE to authenticated using (has_role(auth.uid(), 'admin'::app_role)) with check (has_role(auth.uid(), 'admin'::app_role));
create policy "Anyone can submit a support ticket" on public.support_tickets as PERMISSIVE for INSERT to anon, authenticated with check (((user_id IS NULL) OR (user_id = auth.uid())));
create policy "Users view own tickets" on public.support_tickets as PERMISSIVE for SELECT to authenticated using (((user_id = auth.uid()) OR has_role(auth.uid(), 'admin'::app_role)));
create policy "Admins view all roles" on public.user_roles as PERMISSIVE for SELECT to authenticated using (has_role(auth.uid(), 'admin'::app_role));
create policy "Users view own roles" on public.user_roles as PERMISSIVE for SELECT to authenticated using ((auth.uid() = user_id));
create policy "Hosts view own ledger" on public.wallet_transactions as PERMISSIVE for SELECT to authenticated using (((auth.uid() = host_id) OR has_role(auth.uid(), 'admin'::app_role)));
create policy "No direct ledger deletes" on public.wallet_transactions as RESTRICTIVE for DELETE to anon, authenticated using (false);
create policy "No direct ledger updates" on public.wallet_transactions as RESTRICTIVE for UPDATE to anon, authenticated using (false) with check (false);
create policy "No direct ledger writes" on public.wallet_transactions as RESTRICTIVE for INSERT to anon, authenticated with check (false);

